#!/usr/bin/env python3
"""Generate a stopped, self-contained Flexe profile; never launch an emulator."""
import argparse
import hashlib
import json
import os
from pathlib import Path
import platform
import re
import shutil
import subprocess
import tempfile
from urllib.parse import urlsplit

MOS_VERSION = 'v3.0.2'
MOS_SHA256 = 'd564243283972690933a4554296ad6202ca4ef54572279533a942960846bebae'
MAP_SHA256 = 'd69e60bbce61a7b4b3eef318ba395f11c4e1a5b585755755113992dc94edcb86'

LAUNCHER = r'''#!/usr/bin/env bash
# Generated by this product's create_profile.py. Runtime identities are pinned.
set -euo pipefail
profile_dir="$(cd -- "$(dirname -- "${BASH_SOURCE[0]}")" && pwd)"
[[ $PWD == "$profile_dir" ]] || { echo 'Change to the profile directory first' >&2; exit 2; }
[[ ! -L flexe-agon-emulator && -L flexe-agon-emulator.bin && $(readlink flexe-agon-emulator.bin) == runtime/flexe-agon-emulator && ! -L sdcard ]] || {
    echo 'Invalid profile launcher/raw-link/card layout' >&2; exit 2;
}
[[ $(<.bespoke-vdp-profile) == flexe-vdp.so ]] || { echo 'Wrong backend marker' >&2; exit 2; }
sha256sum --check --status .runtime.sha256 || { echo 'Runtime or firmware identity mismatch' >&2; exit 2; }
sha256sum --check --status .launcher.sha256 || { echo 'Launcher identity mismatch' >&2; exit 2; }
for arg in "$@"; do
    case "$arg" in --vdp*|--mos*|--sdcard*|--firmware*|--prefix*)
        echo 'This profile forbids runtime, firmware and card overrides' >&2; exit 2;;
    esac
done
export LD_LIBRARY_PATH="$profile_dir/lib${LD_LIBRARY_PATH:+:$LD_LIBRARY_PATH}"
export AGON_FLEXE_FIRMWARE="$profile_dir/esp32-firmware.bin"
export AGON_FLEXE_ENGINE="${AGON_FLEXE_ENGINE:-jit}"
[[ $AGON_FLEXE_ENGINE == jit || $AGON_FLEXE_ENGINE == interp ]] || { echo 'Invalid engine' >&2; exit 2; }
unset AGON_FLEXE_ELF
if [[ -f esp32-firmware.elf ]]; then export AGON_FLEXE_ELF="$profile_dir/esp32-firmware.elf"; fi
export AGON_FLEXE_ARTIFACTS="$profile_dir/last-run"
mkdir -p "$AGON_FLEXE_ARTIFACTS"
if [[ -z ${SDL_VIDEODRIVER:-} ]]; then
    if [[ -n ${WAYLAND_DISPLAY:-} ]]; then export SDL_VIDEODRIVER=wayland; else export SDL_VIDEODRIVER=x11; fi
fi
exec ./flexe-agon-emulator.bin --firmware platform --mos "$profile_dir/mos_platform.bin" \
    --sdcard "$profile_dir/sdcard" --vdp "$profile_dir/flexe-vdp.so" "$@"
'''


def digest(path):
    return hashlib.sha256(path.read_bytes()).hexdigest()


def checked(path, expected):
    if not re.fullmatch('[0-9a-f]{64}', expected) or digest(path) != expected:
        raise ValueError('Input checksum mismatch: ' + path.name)


def inspect_elf(path, shared=False):
    data = path.read_bytes()[:20]
    machines = {'x86_64': 62, 'aarch64': 183, 'arm64': 183}
    if len(data) < 20 or data[:6] != b'\x7fELF\x02\x01':
        raise ValueError('Expected a Linux 64-bit little-endian ELF: ' + path.name)
    if int.from_bytes(data[18:20], 'little') != machines.get(platform.machine()):
        raise ValueError('Input architecture does not match this host: ' + path.name)
    if shared and int.from_bytes(data[16:18], 'little') != 3:
        raise ValueError('Backend must be a shared ELF object')


def create(args):
    target = args.output.absolute()
    if target.exists() or target.is_symlink():
        raise ValueError('Output already exists; preserve the existing profile')
    if platform.system() != 'Linux':
        raise ValueError('Initial profile generator supports Linux only')
    if args.firmware_elf and not args.elf_sha256:
        raise ValueError('--firmware-elf requires --elf-sha256')
    if bool(args.library_dir) != bool(args.library_sha256):
        raise ValueError('A library directory requires a checked library SHA256 manifest')
    parsed = urlsplit(args.firmware_source)
    if parsed.scheme != 'https' or not parsed.hostname or parsed.username or parsed.password:
        raise ValueError('Record an HTTPS firmware source without credentials')
    checked(args.mos, MOS_SHA256)
    checked(args.mos_map, MAP_SHA256)
    checked(args.firmware, args.firmware_sha256)
    inspect_elf(args.runtime)
    inspect_elf(args.backend, shared=True)
    symbols = subprocess.check_output(['nm', '-D', '--defined-only', str(args.backend)], text=True)
    names = {line.split()[-1] for line in symbols.splitlines() if line.split()}
    if not {'flexe_vdp_frames', 'flexe_vdp_failed'} <= names:
        raise ValueError('Selected backend is not the actual-firmware Flexe adapter')
    if args.firmware_elf:
        checked(args.firmware_elf, args.elf_sha256)
    libraries = []
    if args.library_dir:
        for row in args.library_sha256.read_text().splitlines():
            expected, name = row.split('  ', 1)
            if Path(name).name != name or '\n' in name or not name.startswith('lib'):
                raise ValueError('Library manifest must contain flat library filenames')
            source = args.library_dir / name
            checked(source, expected)
            libraries.append((source, name))
    target.parent.mkdir(parents=True, exist_ok=True)
    staging = Path(tempfile.mkdtemp(prefix='.flexe-profile-', dir=target.parent))
    try:
        (staging / 'runtime').mkdir()
        (staging / 'sdcard').mkdir()
        (staging / 'lib').mkdir()
        copies = [(args.runtime, 'runtime/flexe-agon-emulator'),
                  (args.backend, 'flexe-vdp.so'), (args.mos, 'mos_platform.bin'),
                  (args.mos_map, 'mos_platform.map'), (args.firmware, 'esp32-firmware.bin')]
        if args.firmware_elf:
            copies.append((args.firmware_elf, 'esp32-firmware.elf'))
        copies += [(source, 'lib/' + name) for source, name in libraries]
        for source, name in copies:
            shutil.copyfile(source, staging / name)
            (staging / name).chmod(0o755 if name.startswith('runtime/') else 0o644)
        (staging / 'flexe-agon-emulator.bin').symlink_to('runtime/flexe-agon-emulator')
        (staging / '.bespoke-vdp-profile').write_text('flexe-vdp.so\n')
        (staging / '.mos-release').write_text(MOS_VERSION + '\n')
        identity = ['flexe-agon-emulator.bin', '.bespoke-vdp-profile', '.mos-release'] + [n for _, n in copies]
        (staging / '.runtime.sha256').write_text(''.join(digest(staging / n) + '  ' + n + '\n' for n in identity))
        launcher = staging / 'flexe-agon-emulator'
        launcher.write_text(LAUNCHER)
        launcher.chmod(0o755)
        (staging / '.launcher.sha256').write_text(digest(launcher) + '  flexe-agon-emulator\n')
        (staging / 'profile.json').write_text(json.dumps({
            'product': 'Flexe Agon Emulator', 'mos_release': MOS_VERSION,
            'mos_source': 'https://github.com/AgonPlatform/agon-mos/releases/tag/' + MOS_VERSION,
            'firmware_source': args.firmware_source,
            'engine_default': 'jit', 'host_machine': platform.machine(),
            'files': {n: digest(staging / n) for n in identity}}, indent=2) + '\n')
        # Claim an absent destination; never replace a directory created by a peer.
        target.mkdir()
        try:
            for child in staging.iterdir():
                child.rename(target / child.name)
        except BaseException:
            shutil.rmtree(target)
            raise
        staging.rmdir()
    except BaseException:
        shutil.rmtree(staging, ignore_errors=True)
        raise
    return target


def main():
    p = argparse.ArgumentParser(description=__doc__)
    for name in ['runtime', 'backend', 'mos', 'mos-map', 'firmware', 'output']:
        p.add_argument('--' + name, type=Path, required=True)
    p.add_argument('--firmware-sha256', required=True)
    p.add_argument('--firmware-source', required=True)
    p.add_argument('--firmware-elf', type=Path)
    p.add_argument('--elf-sha256')
    p.add_argument('--library-dir', type=Path)
    p.add_argument('--library-sha256', type=Path)
    args = p.parse_args()
    try:
        print(create(args))
    except (ValueError, OSError, subprocess.CalledProcessError) as error:
        p.exit(2, str(error) + '\n')


if __name__ == '__main__':
    main()
